// Shape Claude's demo post like a real blog source would: downstream only needs
// title, body, url, author. In production, delete the demo-post nodes and have
// your real source (RSS, webhook, CMS) emit these same fields.
const msg = $input.first().json;
const toolUse = (msg.content || []).find((block) => block.type === 'tool_use' && block.name === 'write_post');
if (!toolUse || !toolUse.input) {
  throw new Error('Claude did not return a write_post tool_use block (stop_reason: ' + (msg.stop_reason || 'unknown') + '). Re-run the workflow.');
}
const d = $('Bloom: get brand').first().json.data || {};
const brand = d.brand || d;
return [{
  json: {
    title: toolUse.input.title,
    body: toolUse.input.body,
    url: brand.url || '',
    author: brand.name || 'Demo author',
  },
}];

